import React, { useState, useEffect } from 'react';
import { getTasks } from '../../api';
import type { Task } from '../../types';
import './TaskBoard.css';

const SKELETON_COUNT = 4;

function renderItems(tasks: Task[] | null): React.ReactNode {
  if (tasks === null) {
    return Array.from({ length: SKELETON_COUNT }, (_, i) => (
      <li key={i} className="task-item task-item-skeleton">
        <span className="skeleton-line" />
      </li>
    ));
  }
  if (tasks.length === 0) {
    return <li className="task-item task-item-empty">No tasks yet</li>;
  }
  return tasks.map((task) => (
    <li key={task.id} className="task-item">
      <span className="task-item-title">{task.title}</span>
    </li>
  ));
}

export function TaskBoard(): React.ReactElement {
  // null = loading; array = loaded
  const [tasks, setTasks] = useState<Task[] | null>(null);

  useEffect(() => {
    getTasks()
      .then(setTasks)
      .catch(() => setTasks([]));
  }, []);

  const count = tasks?.length ?? 0;

  return (
    <div className="task-board">
      <header className="task-board-header">
        <h1 className="task-board-title">Tasks</h1>
        <span className="count-badge" aria-label={`${count} tasks`}>
          {count}
        </span>
      </header>
      <div className="filter-bar" role="toolbar" aria-label="Filters" />
      <ul
        className="task-list"
        aria-label="Tasks"
        aria-busy={tasks === null}
      >
        {renderItems(tasks)}
      </ul>
    </div>
  );
}
